START=datetime.datetime(2026,11,9,22,tzinfo=ZONE);END=datetime.datetime(2026,11,10,8,tzinfo=ZONE)
def now():return datetime.datetime.now(ZONE)
def stamp():return now().isoformat()
def mem(tag):
 raw=Path('/proc/meminfo').read_text();a=int(next(l.split()[1] for l in raw.splitlines() if l.startswith('MemAvailable:')))
 with (D/'resources.jsonl').open('a') as f:f.write(json.dumps(dict(time=stamp(),tag=tag,available_kib=a,meminfo=raw,loadavg=Path('/proc/loadavg').read_text()))+'\n')
 return a
def write(p,j):p.write_text(json.dumps(j,indent=2)+'\n')
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1048576),b''):h.update(b)
 return h.hexdigest()
def export(isa):
 spec=D/(isa+'.command.json');j=json.loads(spec.read_text());unit='afdo-covwhole-'+isa+'-'+str(time.time_ns())
 cmd=['nice','-n','19','ionice','-c3','systemd-run','--user','--scope','--unit='+unit,'-p','MemoryMax=8G','-p','CPUQuota=200%','python3',str(D/'export_child.py'),str(spec)]
 t=time.monotonic();start=stamp();cg=None;peak=0;peak_rss=0;events={};low=0;last=time.monotonic();terminated=False
 with (D/(isa+'.scope.log')).open('w') as log:
  p=subprocess.Popen(cmd,stdout=log,stderr=subprocess.STDOUT)
  while p.poll() is None:
   if cg is None:
    q=subprocess.run(['systemctl','--user','show',unit+'.scope','-p','ControlGroup','--value'],capture_output=True,text=True)
    if q.stdout.strip():cg=Path('/sys/fs/cgroup'+q.stdout.strip())
   if cg:
    try:
     peak=max(peak,int((cg/'memory.peak').read_text()))
     events=dict(v.split() for v in (cg/'memory.events').read_text().splitlines())
     for pid in (cg/'cgroup.procs').read_text().splitlines():
      try:
       vals=Path('/proc/'+pid+'/status').read_text().splitlines()
       peak_rss=max(peak_rss,max([int(v.split()[1]) for v in vals if v.startswith(('VmRSS:','VmHWM:'))] or [0]))
      except (FileNotFoundError,ProcessLookupError):pass
    except (FileNotFoundError,ValueError):pass
   if time.monotonic()-last>=60:
    a=mem('running '+isa);last=time.monotonic();low=low+1 if a<3145728 else 0
    if low>=2:
     terminated=True
     subprocess.run(['systemctl','--user','kill','--signal=TERM',unit+'.scope'],capture_output=True)
     break
   time.sleep(.2)
  rc=p.wait()
 q=subprocess.run(['systemctl','--user','show',unit+'.scope','-p','Result','-p','MemoryPeak'],capture_output=True,text=True)
 child=json.loads(Path(j['result']).read_text()) if Path(j['result']).exists() else None
 out=Path(j['stdout'])
 z=dict(isa=isa,start=start,end=stamp(),scope=unit,command=cmd,scope_rc=rc,seconds=time.monotonic()-t,cgroup_peak_bytes=peak,observed_peak_process_rss_kib=peak_rss,memory_events=events,systemd_after=q.stdout,terminated_low_memory=terminated,child=child,output_bytes=out.stat().st_size if out.exists() else None,output_sha256=sha(out) if out.exists() else None)
 z['state']='成功' if rc==0 and child and child.get('state')=='成功' and not terminated else '失败'
 write(D/(isa+'.scope-result.json'),z);mem('end '+isa);print('导出 已结束',stamp(),isa,z['state'],'ALL-END',flush=True)
 if z['state']!='成功':raise RuntimeError('Export stopped, no retry: '+isa)
 return z
state='未开始';reason=None;rows=[];gates=[];waiting=True
IMMEDIATE_END=now()+datetime.timedelta(minutes=30)
try:
 write(D/'status.json',dict(state='立即检查资源',immediate_end=IMMEDIATE_END.isoformat(),window_start=START.isoformat(),window_end=END.isoformat()))
 mem('baseline')
 for isa in ['thumb','a32']:
  admitted=False
  while now()<END:
   a=mem('admission '+isa);g=dict(time=stamp(),isa=isa,available_kib=a,pass_gate=a>=10485760);gates.append(g);write(D/'gates.json',g)
   with (D/'gates.jsonl').open('a') as f:f.write(json.dumps(g)+'\\n')
   print('门禁',json.dumps(g),flush=True)
   if g['pass_gate']:admitted=True;break
   if now()<IMMEDIATE_END:
    delay=min(300,(IMMEDIATE_END-now()).total_seconds())
   elif now()<START:
    delay=(START-now()).total_seconds()
   else:delay=min(600,max(0,(END-now()).total_seconds()))
   target=time.monotonic()+delay
   while time.monotonic()<target and now()<END:
    time.sleep(min(60,max(0,target-time.monotonic()),max(0,(END-now()).total_seconds())));mem('waiting resource')
  if not admitted:
   reason='窗口结束，内存门禁未满足';break
  if waiting:
   print('等待 已结束',stamp(),'成功：门禁通过','ALL-END',flush=True)
   write(D/'wait-status.json',dict(end=stamp(),state='成功',reason='门禁通过',gates=gates));waiting=False
  write(D/'status.json',dict(state='运行',isa=isa,start=stamp(),completed=len(rows)))
  rows.append(export(isa));state='成功'
 if len(rows)!=2:state='未开始' if not rows else '部分完成'
except BaseException as e:
 reason=repr(e);state='失败';traceback.print_exc()
finally:
 if waiting:
  write(D/'wait-status.json',dict(end=stamp(),state='未开始',reason=reason,gates=gates));print('等待 已结束',stamp(),'未开始',reason,'ALL-END',flush=True)
 write(D/'status.json',dict(state=state,end=stamp(),reason=reason,completed=len(rows),gates=gates,results=rows))
 print('已结束',stamp(),state,reason,'ALL-END',flush=True)
